  const v=set.children.find(c=>c.name==='Type='+type+', State='+state);
  const i=v.createInstance();
  const t=i.children.find(c=>c.type==='TEXT');
  t.characters=label;
  const ic=i.children.find(c=>c.type==='INSTANCE');
  if(ic) ic.visible=showIcon!==false;
  return i;
}
function myPill(state){
  const set=G(MY.Pill);
  const v=set.children.find(c=>c.name==='State='+state);
  return v.createInstance();
}
function myArrow(dir,state){
  const set=G(MY.Arrow);
  const v=set.children.find(c=>c.name==='Dir='+dir+', State='+state);
  return v.createInstance();
}
function myLink(label){
  const set=G(MY.Link);
  const v=set.children.find(c=>c.name==='State=Default');
  const i=v.createInstance();
  i.children.find(c=>c.type==='TEXT').characters=label;
  return i;
}
function myTab(state,label,iconKey){
  const set=G(MY.Tab);
  const v=set.children.find(c=>c.name==='State='+state);
  const i=v.createInstance();
  i.children.find(c=>c.type==='TEXT').characters=label;
  const ic=i.children.find(c=>c.type==='INSTANCE');
  // swap icon by replacing vectors colors; simpler: hide and add correct icon
  ic.visible=false;
  const ni=icon(iconKey,22,state==='Current'?C.white:C.gray);
  i.appendChild(ni);
  i.insertChild(0,ni);
  return i;
}
function myField(placeholder,w,iconKey,focused){
  const c=G(MY.Field).createInstance();
  c.resize(w,56);
  const tf=c.children.find(x=>x.type==='INSTANCE');
  tf.resize(w,56);
  const input=tf.children.find(x=>x.name==='Input');
  input.resize(w,56);
  const ph=input.children.find(x=>x.name==='Placeholder');
  ph.characters=placeholder;
  if(focused){input.strokes=solid(C.orange);input.strokeWeight=2;}
  const ic=c.children.find(x=>x.type==='INSTANCE'&&x.name.startsWith('Icon_'));
  ic.x=w-44;
  if(iconKey&&iconKey!=='marker'){
    ic.visible=false;
    const ni=icon(iconKey,22,C.gray2);
    ni.x=w-44; ni.y=17;
    c.appendChild(ni);
  }
  return c;
}

