function dump(node, depth) {
  const o = {id: node.id, name: node.name, type: node.type, w: Math.round(node.width), h: Math.round(node.height)};
  if (node.layoutMode && node.layoutMode!=='NONE') o.layout = {mode:node.layoutMode, gap:node.itemSpacing, pad:[node.paddingTop,node.paddingRight,node.paddingBottom,node.paddingLeft], pSize:node.primaryAxisSizingMode, cSize:node.counterAxisSizingMode};
  if (node.constraints) o.constraints = node.constraints;
  if (node.type === 'TEXT') { o.chars = node.characters; o.fontSize=node.fontSize; o.style=node.fontName.style; }
  if ('cornerRadius' in node && node.cornerRadius) o.radius = node.cornerRadius;
  if ('fills' in node && node.fills && node.fills.length) o.fills = node.fills.map(f=>f.type==='SOLID'?('#'+Object.values(f.color).map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('')):f.type);
  if ('strokes' in node && node.strokes && node.strokes.length) o.strokes = node.strokes.map(f=>f.type);
  if ('children' in node && depth > 0) o.children = node.children.map(c => dump(c, depth-1));
  return o;
}
