function T(chars, size, style, color, name) {
  const t = figma.createText();
  t.fontName = {family:'Source Sans Pro', style};
  t.characters = chars; t.fontSize = size; t.fills=[{type:'SOLID',color}];
  if (name) t.name = name;
  return t;
}
function recolor(inst, color) {
  inst.findAll(n => n.type==='VECTOR'||n.type==='BOOLEAN_OPERATION'||n.type==='STAR'||n.type==='ELLIPSE'||n.type==='RECTANGLE'||n.type==='LINE').forEach(v=>{
    try{ if(v.fills && v.fills.length) v.fills=[{type:'SOLID',color}]; }catch(e){}
    try{ if(v.strokes && v.strokes.length) v.strokes=[{type:'SOLID',color}]; }catch(e){}
  });
}
function icon(compId, size, color) {
