  const src = G(compId);
  const inst = src.createInstance();
  const s = Math.max(frame.width/src.width, frame.height/src.height);
  inst.resize(src.width*s, src.height*s);
  frame.appendChild(inst);
  inst.x = (frame.width - inst.width)/2;
  inst.y = (frame.height - inst.height)/2;
  return inst;
}
