function recolor(inst, color) {
  inst.findAll(n => ['VECTOR','BOOLEAN_OPERATION','STAR','ELLIPSE','RECTANGLE','LINE'].includes(n.type)).forEach(v=>{
    try{ if(v.fills && v.fills.length) v.fills=[{type:'SOLID',color}]; }catch(e){}
    try{ if(v.strokes && v.strokes.length) v.strokes=[{type:'SOLID',color}]; }catch(e){}
  });
}
function coverPhoto(frame, compId) {
  const src = G(compId);
  const inst = src.createInstance();
  const s = Math.max(frame.width/src.width, frame.height/src.height);
  inst.resize(src.width*s, src.height*s);
  frame.appendChild(inst);
  inst.x = (frame.width - inst.width)/2;
  inst.y = (frame.height - inst.height)/2;
  return inst;
}
