  f.layoutMode = 'HORIZONTAL'; f.primaryAxisSizingMode = 'AUTO'; f.counterAxisSizingMode = 'AUTO';
  f.itemSpacing = gap; f.fills = [];
  parent.appendChild(f); return f;
}
function headRow(parent, title, opts) {
