function dump(node, depth) {
  const o = {id: node.id, n: node.name, t: node.type, w: Math.round(node.width), h: Math.round(node.height)};
  if (node.type === 'TEXT') o.c = node.characters;
  if ('children' in node && depth > 0) o.k = node.children.map(c => dump(c, depth-1));
  return o;
}
