const deals = home.findOne(n=>n.name==='Best deals');
out.dealFull = deals.findAll(t=>t.type==='TEXT').map(t=>t.characters);
const ht = home.findOne(n=>n.name==='HeroText');
out.heroText = ht.findAll(t=>t.type==='TEXT').map(t=>({c:t.characters, size:t.fontSize}));
const hdr = home.findOne(n=>n.name==='Header');
out.headerTexts = hdr.findAll(t=>t.type==='TEXT').map(t=>t.characters);
out.headerInsts = hdr.findAll(n=>n.type==='INSTANCE').map(i=>i.name);
const ftr = home.findOne(n=>n.name==='Footer');
out.footerTexts = ftr.findAll(t=>t.type==='TEXT').map(t=>t.characters.slice(0,100));
return JSON.stringify(out);

const home = figma.getNodeById('65:81');
const ftr = home.findOne(n=>n.name==='Footer');
const t = ftr.findOne(x=>x.type==='TEXT' && x.characters==='Our top cities');
await figma.loadFontAsync(t.fontName);
t.characters = 'Our top cities:';
const insts = ftr.findAll(n=>n.type==='INSTANCE').map(i=>i.name);
return JSON.stringify({fixed: t.characters, insts});
